#!/usr/bin/env python3
"""Build the static, strict-CSP hosted entry from the shared index.html markup.

Run from the repository root: python3 tools/build-hosted-entry.py
This is repository build tooling, not part of the CLI kit shipped to board repos.
"""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]

HEAD = """<!DOCTYPE html>
<!-- Generated by tools/build-hosted-entry.py; edit board/index.html for shared markup. -->
<html lang="en" data-hosted="true" data-kb-markup="{markup_version}">
<head>
<meta charset="UTF-8">
<!-- The first external script installs this policy with only the configured API origin added.
     No other assets or application code run before policy selection. Auth must use self or the API origin. -->
<template id="hostedPolicy"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self' data:; connect-src 'self'; worker-src 'self'; manifest-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; form-action 'none'"></template>
<script src="storage-hosted.js"></script>
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#243447">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="apple-mobile-web-app-title" content="Keeptrack">
<title>Keeptrack</title>
<script src="pwa.js"></script>
<script src="theme.js"></script>
<script src="designmd.js" defer></script>
<link rel="stylesheet" href="board.css">
<link rel="stylesheet" href="ui.css">
<link rel="stylesheet" href="hosted.css">
</head>
"""
FOOTER = """<!-- Plain external scripts preserve source ordering; board.js checks data-kb-markup before wiring the UI. -->
<script src="icons.js"></script>
<script src="ui.js"></script>
<script src="board.js"></script>
</body>
</html>
"""


def generate(index_html: str) -> str:
    """Render in memory, preserving the shared body markup byte for byte as UTF-8.

    Fail on an unfamiliar body/loader shape rather than silently dropping UI or
    copying executable code into the strict entry. The handshake version comes
    from index.html's bootstrap, so it cannot drift independently either.
    """
    body = re.search(r"<body>(.*?)</body>", index_html, re.S)
    if not body:
        raise ValueError("index.html must contain a <body>...</body>")
    parts = re.fullmatch(r"(.*?)<script>(\s*/\* Bootstrap:.*?)</script>\s*", body[1], re.S)
    if (not parts or re.search(r"<script\b", parts[1], re.I)
            or re.search(r"</script\b", parts[2], re.I)):
        raise ValueError("index.html body must end with only the inline Bootstrap script")
    version = re.search(r"var MARKUP = window\.kbMarkup = (\d+);", parts[2])
    if not version:
        raise ValueError("index.html bootstrap must declare its markup handshake version")
    return HEAD.format(markup_version=version[1]) + "<body>" + parts[1] + FOOTER


def main() -> None:
    source = (ROOT / "board/index.html").read_bytes().decode("utf-8")
    (ROOT / "board/hosted.html").write_bytes(generate(source).encode("utf-8"))


if __name__ == "__main__":
    main()
